Lemma dg_rw1_entry : forall (D r dv kp3 s len Ks : Z) t1' t2' a1' a2' a3' a4' s0' s1' s2' s3' t4' (m : word -> option byte) j8 (bs : list byte),
  dg_mem m j8 s0' s1' s2' s3' len Ks bs -> (1 <= len <= 3)%Z -> (1 <= kp3 <= 3)%Z -> (- 2 ^ 31 + 18 <= Ks <= 2 ^ 31 - 3)%Z ->
  (dv = 1 \/ dv = 10 \/ dv = 100)%Z -> (56 <= s <= 59)%Z -> (0 <= r < D)%Z -> (D < 2 ^ 64)%Z ->
  evt rsegs (dg_post Ks) (MS (mkR ra (Z_to_bv 64 (SP0 - 48)) gp tp (Z_to_bv 64 kp) t1' t2' s0' s1' (Z_to_bv 64 D) a1' a2' a3' a4' (Z_to_bv 64 s)
                                  (Z_to_bv 64 buf) (Z_to_bv 64 lenp) s2' s3' s4 s5 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 kp3) t4' (Z_to_bv 64 r) (Z_to_bv 64 dv))
                              F (Z_to_bv 64 0x42674) fc None m (seg_rom rsegs)).
Proof.
  intros until bs. intros HM LR KR KsR Hdv Hs Hr HD.
  pose proof HM as HM0. dg_mem_intro HM.
  zstep. rewrite sx32_small by lia.
  do 5 zstep. zstep.
  assert (KC' : rw_cells rsegs m1 kp [C4 (Z_to_bv 64 (Ks + (kp3 - 1)))])
    by (lazymatch type of KC with rw_cells _ _ _ [C4 (Z_to_bv 64 ?e)] => replace (Ks + (kp3 - 1))%Z with e by lia; exact KC end).
  assert (HM1 : dg_mem m1 j8 s0' s1' s2' s3' len (Ks + (kp3 - 1)) bs).
  { unfold dg_mem. split; [exact ST|]. split; [exact FR|]. split; [exact MU|]. split; [exact WM|]. split; [exact MI|]. split; [exact BU|].
    split; [exact BL|]. split; [exact LE | exact KC']. }
  set (tk := ((dv ≪ (s mod 64)) mod 2 ^ 64)%Z).
  assert (Htk : (1 <= tk < 2 ^ 64)%Z).
  { assert (Hc : (s = 56 \/ s = 57 \/ s = 58 \/ s = 59)%Z) by lia. unfold tk.
    destruct Hdv as [-> | [-> | ->]]; destruct Hc as [-> | [-> | [-> | ->]]]; vm_compute; split; congruence. }
  replace (Z_to_bv 64 (dv ≪ (s mod 64))) with (Z_to_bv 64 tk) by (unfold tk; apply Z_to_bv_mod64).
  zstep. zstep. if_cases K1.
  - zstep. eapply dg_weed1; [exact HM1 | lia | lia | lia].
  - zstep. if_cases K2; zify_cond K2.
    + zstep. eapply dg_weed1; [exact HM1 | lia | lia | lia].
    + zstep. rewrite sx32_small by lia. zstep.
      eapply (dg_rw1_loop (Z.to_nat (D - r)) D r tk len); [reflexivity | exact HM1 | lia | lia | lia | lia | | lia].
      revert K2; unfold tk; rewrite ?Z.mod_small by lia; intros K2; lia.
Qed.

