Lemma dg_l1_k3 : forall (p1 len p2 D s Wp1 Ks : Z) a2' a3' s0' s1' s2' s3' s2x s3x (m : word -> option byte) j8 (bs : list byte),
  dg_mem m j8 s0' s1' s2' s3' len Ks bs -> (0 <= len <= 0)%Z -> (- 2 ^ 31 + 18 <= Ks <= 2 ^ 31 - 3)%Z ->
