          by (f_equal; first [apply le1_lit | symmetry; apply le1_lit | unfold wa; f_equal; lia | reflexivity]);
        pose proof (u8arr_write rsegs m1 buf bs len (Z_to_bv 8 v) BU ltac:(lia)) as BU'
    end.
    clear BU; store_done.
    eassert (HM2 : dg_mem m2 j8 s0' s1' s2' s3' (len + 1) Ks (upd bs (Z.to_nat len) _)).
    { unfold dg_mem. split; [exact ST|]. split; [exact FR|]. split; [exact MU|]. split; [exact WM|]. split; [exact MI|]. split; [exact BU'|].
      split; [rewrite upd_length; exact BL|]. split; [exact LE | exact KC]. }
